import {
  Group,
  Mesh,
  TorusKnotGeometry,
  CylinderGeometry,
  PlaneGeometry,
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
  NodeMaterial,
  color,
  texture,
  uv,
  rotateUV,
  mul,
  mix,
  length,
  vec2,
  add,
  sub,
  float,
  vec3,
  toneMapping,
  normalMap,
  normalScale,
  transparent,
  opacity,
  transformDirection,
  rotateUV,
  textureLoad,
} from 'three/webgpu';
import {
  tsl,
  mixNode,
  lengthNode,
  vec2Node,
  uvNode,
  floatNode,
  colorNode,
  rotateUVNode,
} from 'three/tsl';
import { gsap } from 'gsap';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const root = new Group();
  root.position.set(0, 0, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);
  root.userData.handlers = {};

  // ---------- Textures ----------
  const brushedTexture = ctx.textureLoader('/prism-assets/chrome/brushed-metal.map.png');
  brushedTexture.wrapS = brushedTexture.wrapT = THREE.RepeatWrapping;
  brushedTexture.repeat.set(1, 1);

  // ---------- Torus Knot ----------
  const knotGeom = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knotMat = new MeshStandardNodeMaterial();
  knotMat.color = new THREE.Color('#ffffff');
  knotMat.roughness = 0.55;
  knotMat.metalness = 0.55;
  knotMat.clearcoat = 0.22;
  knotMat.clearcoatRoughness = 0.35;
  knotMat.anisotropy = 0.9;
  knotMat.anisotropyRotation = Math.PI / 2;
  knotMat.envMapIntensity = 0.7;

  // Roughness map with center strength 0.9 (multiply)
  const roughMapNode = mul(texture(brushedTexture), float(0.9));
  knotMat.roughnessNode = roughMapNode;

  // Apply normal map placeholder (strength 0.15) – using same texture as placeholder
  const normalMapNode = mul(texture(brushedTexture), float(0.15));
  knotMat.normalNode = normalMapNode;

  const knotMesh = new Mesh(knotGeom, knotMat);
  knotMesh.position.set(0, 0.4, 0);
  root.add(knotMesh);

  // ---------- Pedestal ----------
  const pedestalGeom = new CylinderGeometry(1.1, 1.1, 0.5, 32, 1);
  const pedestalMat = new MeshStandardNodeMaterial();
  pedestalMat.color = new THREE.Color('#14141a');
  pedestalMat.roughness = 0.7;
  pedestalMat.metalness = 0.35;
  const pedestalMesh = new Mesh(pedestalGeom, pedestalMat);
  // top face at y = -0.35 => center y = -0.35 - height/2
  pedestalMesh.position.set(0, -0.35 - 0.25, 0);
  root.add(pedestalMesh);

  // ---------- Contact Shadow ----------
  const shadowGeom = new PlaneGeometry(3, 3);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });

  const uvNode = uv();
  const distNode = length(sub(uvNode, vec2(0.5, 0.5)));
  const radiusNode = float(0.5);
  const opacityNode = mul(
    float(0.6),
    1.0 - smoothstep(float(0.0), radiusNode, distNode)
  );
  shadowMat.opacityNode = opacityNode;
  shadowMat.colorNode = color('#000000');

  const shadowMesh = new Mesh(shadowGeom, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.y = -0.36;
  root.add(shadowMesh);

  // ---------- Backdrop Gradient ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });

  const uvY = uv().y;
  const gradColor = mix(
    mix(color('#0b0b10'), color('#101017'), smoothstep(float(0.0), float(0.7), uvY)),
    color('#16161d'),
    smoothstep(float(0.7), float(1.0), uvY)
  );
  backdropMat.colorNode = gradColor;
  const backdropMesh = new Mesh(backdropGeom, backdropMat);
  backdropMesh.position.set(0, 0, -3);
  root.add(backdropMesh);

  // ---------- Text ----------
  const headlineOptions = {
    fontFamily: 'Lora',
    fontWeight: 600,
    fontSize: 68,
    letterSpacing: -0.005,
    lineHeight: 1.1,
    color: '#16161d',
    anchorX: 'center',
    anchorY: 'middle',
  };
  const captionOptions = {
    fontFamily: 'JetBrains Mono',
    fontWeight: 400,
    fontSize: 18,
    letterSpacing: 0.08,
    lineHeight: 1.4,
    color: '#e8ecf2',
    anchorX: 'center',
    anchorY: 'middle',
  };

  const headlineMesh = createTextMesh('Material study 03', headlineOptions, ctx.fontAtlas);
  headlineMesh.position.set(0, -1.2, 0);
  root.add(headlineMesh);

  const captionMesh = createTextMesh(
    'GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT',
    captionOptions,
    ctx.fontAtlas
  );
  captionMesh.position.set(0, -1.6, 0);
  root.add(captionMesh);

  // ---------- Apply Cinematic Primitives ----------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === 'function') {
        fn(root, primitive.params);
      }
    }
  }

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    knotGeom.dispose();
    pedestalGeom.dispose();
    shadowGeom.dispose();
    backdropGeom.dispose();
    brushedTexture.dispose();
    knotMat.dispose();
    pedestalMat.dispose();
    shadowMat.dispose();
    backdropMat.dispose();
    // Text meshes may have internal geometries/materials
    if (headlineMesh.geometry) headlineMesh.geometry.dispose();
    if (headlineMesh.material) headlineMesh.material.dispose();
    if (captionMesh.geometry) captionMesh.geometry.dispose();
    if (captionMesh.material) captionMesh.material.dispose();
    gsap.globalTimeline.clear();
  };

  return root;
}
